#include "../../native-vst3/Source/PluginProcessor.h"
#include <iostream>
int main(int argc,char** argv){try{juce::ScopedJuceInitialiser_GUI gui;if(argc!=4)return 2;const juce::File out(argv[1]),runtime(argv[2]),selection(argv[3]);out.createDirectory();auto p=std::make_unique<SpaceInfinityProcessor>(runtime);if(p->ensureBundledPresets().failed())return 3;const auto plan=juce::JSON::parse(selection);for(const auto& row:*plan["retired"].getArray()){const auto key=row["key"].toString();const int index=p->presetBank().indexForKey(key);if(index<0||p->loadBankPreset(index).failed())throw std::runtime_error("Cannot recover "+key.toStdString());const auto file=out.getChildFile(key+".sipreset");const auto result=p->exportPreset(file,true);if(result.failed())throw std::runtime_error(result.getErrorMessage().toStdString());std::cout<<key<<std::endl;}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
